const app=document.querySelector('#app'),progress=document.querySelector('#progress');
const data={clinic:'Central Community Clinic',service:'Routine consultation',slot:'Tuesday · 10:30',name:'',dob:'',phone:'',email:'',reason:'',privacy:false,marketing:false,scenario:'confirmed'};
const set=(step,title,html)=>{progress.textContent=`Step ${step} of 5 · ${title}`;app.innerHTML=html};
function search(){set(1,'Search',`<label for="clinic">Clinic</label><select id="clinic"><option>${data.clinic}</option></select><label for="service">Service</label><select id="service"><option>${data.service}</option></select><button id="go">View availability</button>`);document.querySelector('#go').onclick=availability}
function availability(){set(2,'Availability',`<div class="status">✓ Available times use text as well as visual styling.</div><h2>Choose a time</h2><div class="slots"><button class="slot" aria-pressed="true">${data.slot}<br>Available</button><button class="slot" disabled>Tuesday · 11:00<br>Unavailable</button></div><button id="go">Continue</button><button class="secondary" id="back">Change search</button>`);document.querySelector('#go').onclick=details;document.querySelector('#back').onclick=search}
function details(){set(3,'Details',`<h2>Who is this for?</h2><label for="role">Booking role</label><select id="role"><option>Myself</option><option>Someone else — policy details unresolved</option></select>${['name','dob','phone','email'].map(x=>`<label for="${x}">${x==='dob'?'Date of birth':x[0].toUpperCase()+x.slice(1)}</label><input id="${x}" value="${data[x]}" required>`).join('')}<label for="reason">Reason for visit</label><textarea id="reason">${data.reason}</textarea><p id="err" class="error"></p><button id="go">Review request</button>`);document.querySelector('#go').onclick=()=>{let bad=false;['name','dob','phone','email'].forEach(x=>{data[x]=document.querySelector('#'+x).value.trim();bad||=!data[x]});data.reason=document.querySelector('#reason').value;if(bad){document.querySelector('#err').textContent='Complete each required field before continuing.';return}review()}}
function review(){set(4,'Review',`<h2>Review your request</h2><div class="summary"><b>${data.clinic}</b><br>${data.service}<br>${data.slot}<br>${data.name}</div><label><input type="checkbox" id="privacy" style="width:auto"> I accept the privacy notice</label><label><input type="checkbox" id="marketing" style="width:auto"> Send optional marketing updates</label><label for="scenario">Simulated demo outcome</label><select id="scenario"><option>confirmed</option><option>pending</option><option>stale slot</option><option>rejected</option><option>timeout</option><option>service unavailable</option><option>email failed</option></select><p id="err" class="error"></p><button id="submit">Submit request once</button><button class="secondary" id="edit">Edit details</button>`);document.querySelector('#edit').onclick=details;document.querySelector('#submit').onclick=()=>{if(!document.querySelector('#privacy').checked){document.querySelector('#err').textContent='Accept the privacy notice to continue.';return}data.scenario=document.querySelector('#scenario').value;document.querySelector('#submit').disabled=true;document.querySelector('#submit').textContent='Processing…';setTimeout(outcome,500)}}
function outcome(){let map={confirmed:['✓','Appointment confirmed','Reference DEMO-2048'],'pending':['⌛','Not yet confirmed','Request is pending.'],rejected:['!','Request not confirmed','Choose another time.'],timeout:['?','Outcome unknown','Do not assume this request succeeded.'],'service unavailable':['!','Service unavailable','The request could not be completed.'],'email failed':['✓','Appointment confirmed','Email delivery failed; retain reference DEMO-2048.'],'stale slot':['!','Slot no longer available','Return to availability and select another time.']},o=map[data.scenario];set(5,'Outcome',`<div class="status"><h2>${o[0]} ${o[1]}</h2><p>${o[2]}</p></div><button id="restart">Start again</button>${data.scenario==='stale slot'?'<button class="secondary" id="slots">View refreshed availability</button>':''}`);document.querySelector('#restart').onclick=search;let s=document.querySelector('#slots');if(s)s.onclick=availability}
search();
